import React, { useState } from 'react';

const SignIn = () => {
  const [name, setName] = useState('');
  const [password, setPassword] = useState('');
  const [role, setRole] = useState('');
  const [rememberMe, setRememberMe] = useState(false); // State for the checkbox

  const handleSubmit = (e) => {
    e.preventDefault();
    // Handle sign-in logic here
    console.log('Name:', name);
    console.log('Password:', password);
    console.log('Role:', role);
    console.log('Remember Me:', rememberMe);
  };

  // Styles for the form
  const formStyle = {
    padding: '20px',
    width: '300px',
  };

  const labelStyle = {
    marginBottom: '8px', // Space between label and input field
    display: 'block', // Make labels block elements to have full width
  };

  const inputStyle = {
    marginBottom: '16px', // Space after input field
    width: '100%', // Make input full width
    padding: '8px', // Optional: add padding for better touch targets
  };

  return (
    <div style={formStyle}>
      <h2>Sign In</h2>
      <form onSubmit={handleSubmit}>
        <div>
          <label style={labelStyle}>Role:</label>
          <select
            value={role}
            onChange={(e) => setRole(e.target.value)}
            required
            style={inputStyle}
          >
            <option value="">Select your role</option>
            <option value="user">User</option>
            <option value="admin">Admin</option>
            <option value="guest">Guest</option>
          </select>
        </div>
        <div>
          <label style={labelStyle}>Name:</label>
          <input
            type="text"
            value={name}
            onChange={(e) => setName(e.target.value)}
            placeholder="Enter your username"
            required
            style={inputStyle}
          />
        </div>
        <div>
          <label style={labelStyle}>Password:</label>
          <input
            type="password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            placeholder="Enter your password"
            required
            style={inputStyle}
          />
        </div>
        <div>
          <input
            type="checkbox"
            checked={rememberMe}
            onChange={(e) => setRememberMe(e.target.checked)}
          />
          <label style={{ marginLeft: '8px' }}> Remember Me</label>
        </div>
        <button type="submit" style={{ marginTop: '16px' }}>Sign In</button>
      </form>
    </div>
  );
};

export default SignIn;
